275:     this.viewSubcriterios = false;
276:     let inscritosData: any[] = [];
277:     const inscripciones: any = await this.recuperarInscripciones(this.selectedcurricular, this.periodo)
278:     for (const inscripcion of inscripciones) {
279:       const persona: any = await this.consultarTercero(inscripcion.PersonaId);
280:       if (Array.isArray(persona) && persona.length === 0) {
281:         continue;
282:       }
283: 
284:       const dataInscrito: any = {
285:         "Credencial": 123,
286:         "Nombre": persona.NombreCompleto
287:       }
288:       inscritosData.push(dataInscrito);
289:     }
290:     inscritosData = this.agregarColumnasCriterios(inscritosData)
291:     this.datasourcePuntajeAspirantes = new MatTableDataSource(inscritosData);
292:     this.datasourcePuntajeAspirantes.paginator = this.paginator3;
293:     this.datasourcePuntajeAspirantes.sort = this.sort3;
294:     this.viewSubcriterios = true;
295:     this.loading = false;
296:   }
