298:   agregarColumnasCriterios(data: any) {
299:     this.requisitosActuales.forEach((element: any) => {
300:       this.columnspuntajeaspirantes.push(element.RequisitoId.Nombre);
301:     });
302:     for (const item of data) {
303:       for (const requisito of this.requisitosActuales) {
304:         item[requisito.RequisitoId.Nombre] = "";
305:       }
306:     }
307:     return data;
308:   }
