396:           const blob = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
397: 
398:           // Paso 4: Crear un enlace de descarga
399:           const link = document.createElement('a');
400:           link.href = window.URL.createObjectURL(blob);
401:           link.download = 'ListadoEvaluacion.xlsx';
402:           // Paso 5: Hacer clic en el enlace de descarga programáticamente
403:           link.click();
404:           this.loading = false;
405:         } else {
406:           this.popUpManager.showErrorAlert(this.translate.instant('evaluacionPregrado.error_descarga'));
407:           this.loading = false;
408:         }
409:       }),
410:       (error: any) => {
