41:   ngOnInit() {
42:     this.criterios = [];
43:     this.admisiones.get("requisito?limit=0&query=Activo:true").subscribe(
44:       (response: any) => {
45:         this.criterios = <Criterio[]>(
46:           response.filter((c: any) => c["RequisitoPadreId"] === null)
47:         );
48:         this.criterios.forEach((criterio) => {
49:           this.admisiones
50:             .get(
51:               "requisito?limit=0&query=Activo:true,RequisitoPadreId.Id:" +
52:                 criterio.Id
53:             )
54:             .subscribe(
55:               (response: any) => {
56:                 if (
57:                   response.length > 0 &&
58:                   Object.keys(response[0]).length > 0
59:                 ) {
60:                   criterio.Subcriterios = <Criterio[]>response;
61:                 } else {
62:                   criterio.Subcriterios = [];
63:                 }
64:               },
65:               (error: any) => {
66:                 criterio.Subcriterios = [];
67:                 this.popUpManager.showErrorToast(
68:                   this.translate.instant("admision.error_cargar")
69:                 );
70:               }
71:             );
72:         });
73:         this.criterioSource = new MatTableDataSource(this.criterios);
74: 
75:         setTimeout(() => {
76:           this.criterioSource.paginator = this.paginator;
77:           this.criterioSource.sort = this.sort;
78:         }, 300);
79:       },
80:       (error: any) => {
81:         this.popUpManager.showErrorToast(
82:           this.translate.instant("admision.error_cargar")
83:         );
84:       }
85:     );
