97:   agregarCriterio() {
98:     // Verifica el tamaño de la pantalla
99:     if (window.innerWidth < 600) {
100:       // Configuración para dispositivos móviles
101:       this.dialogConfig.width = "90%";
102:       this.dialogConfig.height = "80%";
103:     } else {
104:       // Configuración para pantallas más grandes
105:       this.dialogConfig.width = "600px";
106:       this.dialogConfig.maxHeight = "80%";
107:     }
108:     this.dialogConfig.data = {};
109:     const criterioDialog = this.dialog.open(
110:       DialogoCriteriosComponent,
111:       this.dialogConfig
112:     );
113:     criterioDialog.afterClosed().subscribe((criterio: Criterio) => {
114:       if (criterio) {
115:         this.admisiones
116:           .post("requisito", criterio)
